package com.inventra.backend.controller; import com.inventra.backend.dto.ReturnRequest; import com.inventra.backend.model.ReturnRecord; import com.inventra.backend.service.ReturnService; import jakarta.validation.Valid; import org.springframework.web.bind.annotation.*; import java.util.*; @RestController @RequestMapping("/api/returns") public class ReturnController {private final ReturnService s;public ReturnController(ReturnService s){this.s=s;}@PostMapping public ReturnRecord request(@Valid @RequestBody ReturnRequest r){return s.request(r);}@GetMapping public List<ReturnRecord> all(){return s.all();}@PostMapping("/{id}/accept") public ReturnRecord accept(@PathVariable String id){return s.accept(id);}@PostMapping("/{id}/reject") public ReturnRecord reject(@PathVariable String id){return s.reject(id);}}
